int run_ingest(const char* input, const char* output) {
    const pid_t child = fork();
    if (child == -1) {
        throw std::runtime_error("fork failed");
    }
    if (child == 0) {
        execl("/app/bin/loam-ingest", "loam-ingest", input, output, nullptr);
        _exit(127);
    }
    int status = 0;
    if (waitpid(child, &status, 0) == -1) {
