    let mut pages = Vec::new();
    for (id, chunk) in cells.chunks(width).enumerate() {
        let values: Vec<i64> = chunk.iter().map(|cell| cell.amount).collect();
        let present: Vec<u8> = chunk.iter().map(|cell| cell.present).collect();
