        let region_low = regions.first().cloned().unwrap_or_default();
        let region_high = regions.last().cloned().unwrap_or_default();
        pages.push(Page {
            id,
            generation: 3,
            mark,
            region_low,
            region_high,
            cells: chunk.to_vec(),
        });
    }
    Ok(pages)
}
